# owner: platform
import unittest

from hourglass.gaps import uncovered_gaps
from hourglass.models import Span

NINE_TO_FIVE = Span(540, 1020)


class UncoveredGapTests(unittest.TestCase):
    def test_gap_between_two_shifts(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            uncovered_gaps(worked, NINE_TO_FIVE),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = [Span(600, 900)]
        self.assertEqual(
            uncovered_gaps(worked, NINE_TO_FIVE),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 15:00-17:00 (120 min)"
            ]
        )

    def test_overlapping_and_touching_merge(self):
        worked = [
            Span(540, 700),
            Span(600, 720),
            Span(720, 800)
        ]
        self.assertEqual(
            uncovered_gaps(worked, NINE_TO_FIVE),
            ["gap 13:20-17:00 (220 min)"]
        )

    def test_unsorted_input(self):
        worked = [Span(780, 1020), Span(540, 720)]
        self.assertEqual(
            uncovered_gaps(worked, NINE_TO_FIVE),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(
            uncovered_gaps([], Span(540, 600)),
            ["gap 09:00-10:00 (60 min)"]
        )

    def test_fully_covered(self):
        self.assertEqual(
            uncovered_gaps([NINE_TO_FIVE], NINE_TO_FIVE),
            []
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            uncovered_gaps([Span(480, 600)], NINE_TO_FIVE)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            uncovered_gaps([Span(900, 1080)], NINE_TO_FIVE)
